void hungarian(int n, const double *cost, int *assignment) {
    double *u = calloc(n, sizeof(double));  // row potentials
    double *v = calloc(n, sizeof(double));  // col potentials
    int *p = malloc(n * sizeof(int));       // p[j] = row matched to col j
    int *way = malloc(n * sizeof(int));     // way[j] = previous col in path
