        int j0 = 0;
        for (int j = 0; j < n; j++) { minv[j] = INF; used[j] = 0; }
        do {
            used[j0] = 1;
            int i0 = p[j0];
            double delta = INF;
            int j1 = -1;
            for (int j = 1; j <= n; j++) {
                if (!used[j]) {
                    double cur = cost[i0*n + (j-1)] - u[i0] - v[j-1];
                    if (cur < minv[j]) {
                        minv[j] = cur;
                        way[j] = j0;
                    }
                    if (minv[j] < delta) {
                        delta = minv[j];
                        j1 = j;
                    }
                }
