            }
            j0 = j1;
        } while (p[j0] != -1);
        // augment
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0 != 0);
    }
    for (int j = 1; j <= n; j++) {
        if (p[j] != -1) assignment[p[j]] = j-1;
    }
}
