#define INF DBL_MAX

// cost: n x n row-major
// assignment[i] = column assigned to row i
void hungarian(int n, const double *cost, int *assignment)
{
    double *u = (double*)calloc(n, sizeof(double));
    double *v = (double*)calloc(n, sizeof(double));
    int *p = (int*)malloc((n+1) * sizeof(int));   // p[j] = row matched to column j (1-based col index)
    int *way = (int*)malloc((n+1) * sizeof(int));
    double *minv = (double*)malloc((n+1) * sizeof(double));
    char *used = (char*)malloc((n+1) * sizeof(char));

    for (int j = 0; j <= n; j++) p[j] = -1;

    for (int i = 0; i < n; i++) {
        p[0] = i;
        int j0 = 0;
        for (int j = 0; j <= n; j++) { minv[j] = INF; used[j] = 0; }
        do {
            used[j0] = 1;
            int i0 = p[j0];
            double delta = INF;
            int j1 = -1;
            for (int j = 1; j <= n; j++) {
                if (!used[j]) {
                    double cur = cost[i0*n + (j-1)] - u[i0] - v[j-1];
                    if (cur < minv[j]) {
                        minv[j] = cur;
                        way[j] = j0;
                    }
                    if (minv[j] < delta) {
                        delta = minv[j];
                        j1 = j;
                    }
                }
            }
            for (int j = 0; j <= n; j++) {
                if (used[j]) {
                    u[p[j]] += delta;
                    v[j-1] -= delta;
                } else {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
        } while (p[j0] != -1);
        // augment
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0 != 0);
    }
    for (int j = 1; j <= n; j++) {
        if (p[j] != -1) assignment[p[j]] = j-1;
    }
    free(u); free(v); free(p); free(way); free(minv); free(used);
}
